def grep(d, pat, w=250, maxn=6):
    n=0
    for m in re.finditer(pat, d, flags=re.I):
        s=max(0,m.start()-w); print("...", d[s:m.end()+w].replace("\n"," "), "...\n"); n+=1
        if n>=maxn: break
    if n==0: print("NO HIT", pat)
